-- Generated by pwc2dbt from mapping m_FL_JS_MARTS_ENRICHED, target instance PRODUCT_DAILY_PERFORMANCE. Do not edit.

with

sq_stg_supplies as (

    select
        cast(stg_supplies.supply_cost as double) as supply_cost,
        cast(stg_supplies.is_perishable as double) as is_perishable,
        cast(stg_supplies.product_id as varchar) as product_id
    from {{ ref('stg_supplies') }} as stg_supplies

),

agg_supplies_by_product as (

    select
        sq_stg_supplies.product_id as product_id,
        sum(sq_stg_supplies.supply_cost) as supply_cost_per_product,
        max(sq_stg_supplies.is_perishable) as has_perishable_supply
    from sq_stg_supplies
    group by sq_stg_supplies.product_id

),

sq_stg_orders as (

    select
        cast(stg_orders.order_id as varchar) as order_id,
        cast(stg_orders.customer_id as varchar) as customer_id,
        cast(stg_orders.location_id as varchar) as location_id,
        cast(stg_orders.ordered_at_day as timestamp) as ordered_at_day
    from {{ ref('stg_orders') }} as stg_orders

),

sq_stg_order_items as (

    select
        cast(stg_order_items.order_item_id as varchar) as order_item_id,
        cast(stg_order_items.order_id as varchar) as order_id,
        cast(stg_order_items.product_id as varchar) as product_id
    from {{ ref('stg_order_items') }} as stg_order_items

),

jnr_items_orders as (

    select
        master.order_item_id as order_item_id,
        master.product_id as product_id,
        detail.customer_id as customer_id,
        detail.location_id as location_id,
        detail.ordered_at_day as ordered_at_day
    from sq_stg_orders as detail
    inner join sq_stg_order_items as master
        on master.order_id = detail.order_id

),

sq_stg_products as (

    select
        cast(stg_products.product_id as varchar) as product_id,
        cast(stg_products.product_name as varchar) as product_name,
        cast(stg_products.product_type as varchar) as product_type,
        cast(stg_products.product_price as double) as product_price
    from {{ ref('stg_products') }} as stg_products

),

jnr_add_products as (

    select
        master.order_item_id as order_item_id,
        master.product_id as product_id,
        master.customer_id as customer_id,
        master.location_id as location_id,
        master.ordered_at_day as ordered_at_day,
        detail.product_name as product_name,
        detail.product_type as product_type,
        detail.product_price as product_price
    from sq_stg_products as detail
    inner join jnr_items_orders as master
        on master.product_id = detail.product_id

),

sq_stg_customers as (

    select
        cast(stg_customers.customer_id as varchar) as customer_id
    from {{ ref('stg_customers') }} as stg_customers

),

jnr_add_customers as (

    select
        master.order_item_id as order_item_id,
        master.product_id as product_id,
        master.location_id as location_id,
        master.ordered_at_day as ordered_at_day,
        master.product_name as product_name,
        master.product_type as product_type,
        master.product_price as product_price
    from sq_stg_customers as detail
    left join jnr_add_products as master
        on master.customer_id = detail.customer_id

),

sq_stg_locations as (

    select
        cast(stg_locations.location_id as varchar) as location_id
    from {{ ref('stg_locations') }} as stg_locations

),

jnr_add_locations as (

    select
        master.order_item_id as order_item_id,
        master.product_id as product_id,
        master.ordered_at_day as ordered_at_day,
        master.product_name as product_name,
        master.product_type as product_type,
        master.product_price as product_price
    from sq_stg_locations as detail
    left join jnr_add_customers as master
        on master.location_id = detail.location_id

),

jnr_add_supplies as (

    select
        master.order_item_id as order_item_id,
        master.product_id as product_id,
        master.ordered_at_day as ordered_at_day,
        master.product_name as product_name,
        master.product_type as product_type,
        master.product_price as product_price,
        detail.supply_cost_per_product as supply_cost_per_product,
        detail.has_perishable_supply as has_perishable_supply
    from agg_supplies_by_product as detail
    left join jnr_add_locations as master
        on master.product_id = detail.product_id

),

exp_item_calculations as (

    select
        jnr_add_supplies.order_item_id as order_item_id,
        jnr_add_supplies.product_id as product_id,
        jnr_add_supplies.ordered_at_day as ordered_at_day,
        jnr_add_supplies.product_name as product_name,
        jnr_add_supplies.product_type as product_type,
        jnr_add_supplies.product_price as item_revenue,
        (case when (jnr_add_supplies.supply_cost_per_product is null) then 0 else jnr_add_supplies.supply_cost_per_product end) as item_cogs,
        jnr_add_supplies.product_price - (case when (jnr_add_supplies.supply_cost_per_product is null) then 0 else jnr_add_supplies.supply_cost_per_product end) as item_gross_profit,
        (case when (jnr_add_supplies.has_perishable_supply is null) then 0 else jnr_add_supplies.has_perishable_supply end) as has_perishable_supply
    from jnr_add_supplies

),

agg_by_product_day as (

    select
        exp_item_calculations.product_id as product_id,
        exp_item_calculations.product_name as product_name,
        exp_item_calculations.product_type as product_type,
        exp_item_calculations.ordered_at_day as ordered_at_day,
        count(exp_item_calculations.order_item_id) as units_sold,
        sum(exp_item_calculations.item_revenue) as revenue,
        sum(exp_item_calculations.item_cogs) as cogs,
        sum(exp_item_calculations.item_gross_profit) as gross_profit,
        max(exp_item_calculations.has_perishable_supply) as perishable_sales_flag
    from exp_item_calculations
    group by exp_item_calculations.product_id, exp_item_calculations.product_name, exp_item_calculations.product_type, exp_item_calculations.ordered_at_day

),

exp_product_metrics as (

    select
        agg_by_product_day.product_id as product_id,
        agg_by_product_day.product_name as product_name,
        agg_by_product_day.product_type as product_type,
        agg_by_product_day.ordered_at_day as ordered_at_day,
        agg_by_product_day.units_sold as units_sold,
        agg_by_product_day.revenue as revenue,
        agg_by_product_day.cogs as cogs,
        agg_by_product_day.gross_profit as gross_profit,
        agg_by_product_day.perishable_sales_flag as perishable_sales_flag,
        case when agg_by_product_day.revenue = 0 then 0 else agg_by_product_day.gross_profit / agg_by_product_day.revenue end as margin_pct
    from agg_by_product_day

)

select
    cast(exp_product_metrics.product_id as varchar) as product_id,
    cast(exp_product_metrics.product_name as varchar) as product_name,
    cast(exp_product_metrics.product_type as varchar) as product_type,
    cast(exp_product_metrics.ordered_at_day as timestamp) as ordered_at_day,
    cast(exp_product_metrics.units_sold as double) as units_sold,
    cast(exp_product_metrics.revenue as decimal(12,2)) as revenue,
    cast(exp_product_metrics.cogs as decimal(12,2)) as cogs,
    cast(exp_product_metrics.gross_profit as decimal(12,2)) as gross_profit,
    cast(exp_product_metrics.perishable_sales_flag as decimal(10,4)) as margin_pct,
    cast(exp_product_metrics.margin_pct as decimal(1,0)) as perishable_sales_flag
from exp_product_metrics
